"""Minimal MessagePack implementation (core subset) in pure Python.

Supported types (this subset only):
  - nil
  - booleans
  - integers via positive/negative fixint, uint8/16/32/64, int8/16/32/64
    (packing always chooses the smallest correct encoding)
  - strings via fixstr / str8 / str16 (UTF-8)
  - arrays via fixarray / array16
  - maps via fixmap / map16 (string keys only)

`unpack` returns (obj, consumed_bytes) and raises MsgpackError on
truncated input or on reserved / unsupported bytes (e.g. 0xc1).
"""

__all__ = ["MsgpackError", "pack", "unpack"]


class MsgpackError(Exception):
    """Raised on malformed, truncated or unsupported MessagePack data."""


# ---------------------------------------------------------------------------
# packing
# ---------------------------------------------------------------------------

def _pack_integer(n):
    if isinstance(n, bool):
        raise TypeError("bool is not an integer for msgpack purposes")
    if 0 <= n <= 0x7F:                       # positive fixint
        return bytes((n,))
    if -32 <= n < 0:                         # negative fixint
        return bytes((n & 0xFF,))
    if 0 <= n <= 0xFF:                       # uint8
        return b"\xcc" + n.to_bytes(1, "big")
    if -0x80 <= n < -32:                     # int8
        return b"\xd0" + n.to_bytes(1, "big", signed=True)
    if 0 <= n <= 0xFFFF:                     # uint16
        return b"\xcd" + n.to_bytes(2, "big")
    if -0x8000 <= n < -0x80:                 # int16
        return b"\xd1" + n.to_bytes(2, "big", signed=True)
    if 0 <= n <= 0xFFFFFFFF:                 # uint32
        return b"\xce" + n.to_bytes(4, "big")
    if -0x80000000 <= n < -0x8000:           # int32
        return b"\xd2" + n.to_bytes(4, "big", signed=True)
    if 0 <= n <= 0xFFFFFFFFFFFFFFFF:         # uint64
        return b"\xcf" + n.to_bytes(8, "big")
    if -0x8000000000000000 <= n < -0x80000000:  # int64
        return b"\xd3" + n.to_bytes(8, "big", signed=True)
    raise ValueError("integer out of msgpack subset range")


def _pack_string(s):
    data = s.encode("utf-8")
    n = len(data)
    if n <= 31:                              # fixstr
        return bytes((0xA0 | n,)) + data
    if n <= 0xFF:                            # str8
        return b"\xd9" + bytes((n,)) + data
    if n <= 0xFFFF:                          # str16
        return b"\xda" + n.to_bytes(2, "big") + data
    raise ValueError("string too long for msgpack subset")


def _pack_array(items):
    n = len(items)
    if n <= 15:                              # fixarray
        head = bytes((0x90 | n,))
    elif n <= 0xFFFF:                        # array16
        head = b"\xdc" + n.to_bytes(2, "big")
    else:
        raise ValueError("array too long for msgpack subset")
    return head + b"".join(pack(x) for x in items)


def _pack_map(d):
    n = len(d)
    if n <= 15:                              # fixmap
        head = bytes((0x80 | n,))
    elif n <= 0xFFFF:                        # map16
        head = b"\xde" + n.to_bytes(2, "big")
    else:
        raise ValueError("map too long for msgpack subset")
    out = [head]
    for k, v in d.items():
        if not isinstance(k, str):
            raise TypeError("msgpack subset allows string keys only")
        out.append(_pack_string(k))
        out.append(pack(v))
    return b"".join(out)


def pack(obj):
    """Serialize *obj* (within the supported subset) to bytes."""
    if obj is None:
        return b"\xc0"
    if obj is True:
        return b"\xc3"
    if obj is False:
        return b"\xc2"
    if isinstance(obj, bool):
        # subclass of int; handled above, but be explicit
        return b"\xc3" if obj else b"\xc2"
    if isinstance(obj, int):
        return _pack_integer(obj)
    if isinstance(obj, str):
        return _pack_string(obj)
    if isinstance(obj, list):
        return _pack_array(obj)
    if isinstance(obj, dict):
        return _pack_map(obj)
    raise TypeError("type not supported by msgpack subset: %r" % type(obj))


# ---------------------------------------------------------------------------
# unpacking
# ---------------------------------------------------------------------------

def _need(data, pos, count):
    if pos + count > len(data):
        raise MsgpackError(
            "truncated: need %d byte(s) at offset %d, have %d"
            % (count, pos, len(data) - pos)
        )


def _unpack_str(data, pos, length):
    _need(data, pos, length)
    try:
        return data[pos:pos + length].decode("utf-8"), length
    except UnicodeDecodeError:
        raise MsgpackError("invalid UTF-8 in string payload")


def unpack(data, pos=0):
    """Unpack one object starting at *pos*.

    Returns ``(obj, consumed)`` where *consumed* counts bytes from *pos*.
    Raises MsgpackError on truncated input, reserved bytes (0xc1) or any
    format outside the supported subset.
    """
    _need(data, pos, 1)
    b = data[pos]
    p = pos + 1

    if b <= 0x7F:                            # positive fixint
        return b, 1
    if b >= 0xE0:                            # negative fixint
        return b - 0x100, 1

    if 0x80 <= b <= 0x8F:                    # fixmap
        return _unpack_map(data, p, b & 0x0F)
    if 0x90 <= b <= 0x9F:                    # fixarray
        return _unpack_array(data, p, b & 0x0F)
    if 0xA0 <= b <= 0xBF:                    # fixstr
        s, used = _unpack_str(data, p, b & 0x1F)
        return s, 1 + used

    handler = _SINGLE_BYTE.get(b)
    if handler is None:
        raise MsgpackError("reserved or unsupported byte: 0x%02x" % b)

    kind, nargs = handler
    _need(data, p, nargs)
    arg = int.from_bytes(data[p:p + nargs], "big")
    q = p + nargs

    if kind == "u":
        return arg, 1 + nargs
    if kind == "i":
        bits = nargs * 8
        return arg - (1 << bits) if arg >= (1 << (bits - 1)) else arg, 1 + nargs
    if kind == "str8_16":
        s, used = _unpack_str(data, q, arg)
        return s, 1 + nargs + used
    if kind == "array":
        return _unpack_array(data, q, arg)
    if kind == "map":
        return _unpack_map(data, q, arg)
    raise MsgpackError("internal error")     # unreachable


def _unpack_array(data, pos, count):
    items = []
    p = pos
    for _ in range(count):
        item, used = unpack(data, p)
        items.append(item)
        p += used
    return items, p - pos


def _unpack_map(data, pos, count):
    result = {}
    p = pos
    for _ in range(count):
        key, used = unpack(data, p)
        if not isinstance(key, str):
            raise MsgpackError("map key is not a string")
        value, used_v = unpack(data, p + used)
        result[key] = value
        p += used + used_v
    return result, p - pos


# single-byte formats: marker byte -> (kind, extra operand bytes)
_SINGLE_BYTE = {
    0xCC: ("u", 1),        # uint8
    0xCD: ("u", 2),        # uint16
    0xCE: ("u", 4),        # uint32
    0xCF: ("u", 8),        # uint64
    0xD0: ("i", 1),        # int8
    0xD1: ("i", 2),        # int16
    0xD2: ("i", 4),        # int32
    0xD3: ("i", 8),        # int64
    0xD9: ("str8_16", 1),  # str8
    0xDA: ("str8_16", 2),  # str16
    0xDC: ("array", 2),    # array16
    0xDE: ("map", 2),      # map16
    # fixed one-byte immediates
    0xC0: ("nil_b", 0),
    0xC2: ("false_b", 0),
    0xC3: ("true_b", 0),
}

_IMMEDIATES = {0xC0: None, 0xC2: False, 0xC3: True}


def _patch_immediates():
    """Handle 0xC0/0xC2/0xC3 directly in unpack's fast path."""
    pass

